377	            explained={explained} explainState={explainState} explainError={explainError} interpretError={interpretError}
378	            evaluateError={evaluateError} runs={runs} trace={trace} selected={panel} onSelect={selectStep} />
379	          {final && evaluation && (
380	            <button type="button" className="btn btn--small" style={{ marginTop: 12 }} onClick={() => setView("results")}>See the results</button>
381	          )}
382	        </section>
383	        )}
384	
385	        {view === "results" && (
386	        <section id="report" className="ws__report anchor" aria-labelledby="report-title">
387	          <div className="report__top">
388	            <h2 id="report-title" className="report__title">Report</h2>
389	            {evaluation && (
390	              <div className="report__actions">
391	                <button type="button" className="btn btn--outline btn--small" onClick={openGraph}>
392	                  <GraphIcon /> Open knowledge graph
393	                </button>
394	                <button type="button" className="btn btn--small" onClick={exportPdf} disabled={pdfBusy}
395	                  title={explainState === "running" ? "The written brief is still being prepared; export now leaves it out" : undefined}>
396	                  <DownloadIcon /> {pdfBusy ? "Preparing PDF…" : "Export PDF"}
397	                </button>
398	              </div>
399	            )}
400	            {features.length > 1 && (
401	              <div className="chips" role="group" aria-label="Feature">
402	                {features.map((f, i) => (
403	                  <button key={f.feature} type="button" className="chip" aria-pressed={i === featIdx} onClick={() => { setFeatIdx(i); setCellKey(null); }}>
404	                    {f.feature}
405	                  </button>
406	                ))}
407	              </div>
408	            )}
409	          </div>
410	          {pdfError && <p className="note note--error small">The PDF could not be created: {pdfError}</p>}
411	          {!evaluation ? (
412	            <div className="report__empty">
413	              <p><strong>The report appears here once the evidence is computed.</strong></p>
414	              <p className="small muted">{phase === "review" ? "Choose what to check in the side panel to continue." : "First your idea is broken down into topics from customer feedback, then you choose what to check."}</p>
415	            </div>
416	          ) : (
417	            <>
418	              <div className="tabs" role="tablist" aria-label="Report sections">
419	                {TABS.map((t) => (
420	                  <button key={t.id} id={`tab-${t.id}`} className="tab" role="tab" aria-selected={tab === t.id} aria-controls="report-panel" onClick={() => setTab(t.id)}>
421	                    {t.label}
422	                  </button>
423	                ))}
424	              </div>
425	              <div id="report-panel" role="tabpanel" aria-labelledby={`tab-${tab}`} className="report__panel">
426	                {tab === "summary" && (final ? (
427	                  <PlainReport evaluation={evaluation} feature={fr} explained={explained} explainState={explainState} explainError={explainError}
428	                    onExplain={() => explain(evaluation.evaluation_id)} onShowNode={showNode} onOpenMetrics={() => setTab("markets")} />
429	                ) : (
430	                  <div className="report__pending" role="status">
431	                    <p className="side__working-title"><span className="spinner" aria-hidden /> Preparing your summary</p>
432	                    <p className="small">The summary appears once the brief has been written and every sentence fact-checked, so you only see checked results.</p>
433	                    <ol>
434	                      <li>Scored against the data: done</li>
435	                      <li>Writing the brief: {explainState === "running" ? "in progress" : "starting"}</li>
436	                      <li>Fact-checking every sentence: waiting</li>
437	                    </ol>
438	                    <p className="caption">The raw numbers are already in the Metrics tab if you want to look now.</p>
439	                  </div>
440	                ))}
441	                {tab === "markets" && (fr && cell ? (
442	                  <div className="stack">
443	                    <p className="small muted measure">
444	                      The priority score (0 to 1) says how strongly customers give a reason to act, for each series and market. It combines complaints,
445	                      how often the topic comes up, requests, customer-study weakness and how many cars are sold there. Select a cell to see its evidence.
446	                    </p>
447	                    <div className="decision-grid">
448	                      <DecisionMatrix cells={fr.cells} models={evaluation.result.models} markets={evaluation.result.markets} selected={`${cell.model}|${cell.market}`} onSelect={setCellKey} />
449	                      <EvidencePanel cell={cell} fitment={fr.price_ladder.find((l) => l.model === cell.model)} />
450	                    </div>
451	                  </div>
452	                ) : <p className="small muted">No feature was evaluated, so there is no series × market evidence.</p>)}
453	                {tab === "equipment" && (<>{fr ? (
454	                  <div className="stack">
455	                    <p className="small muted">German price lists, July 2026. EUR incl. 19% VAT. Prices for other markets are not in the data.</p>
456	                    <PriceLadder ladder={fr.price_ladder} />
457	                    {fr.specs.length > 0 && (
458	                      <details>
459	                        <summary>Technical data linked to {fr.feature} ({fr.specs.length} values)</summary>
460	                        <div className="table-scroll" style={{ marginTop: 12 }}>
461	                          <table className="table">
462	                            <thead><tr><th>Series</th><th>Variant</th><th>Attribute (as printed)</th><th>Value</th><th>Page</th></tr></thead>
463	                            <tbody>
464	                              {fr.specs.map((s, i) => (
465	                                <tr key={i}><td>{MODEL_NAMES[s.model]}</td><td>{s.variant}</td><td>{s.attribute}</td><td className="num">{s.value}</td><td className="caption">{s.model} p.{s.page}</td></tr>
466	                              ))}
467	                            </tbody>
468	                          </table>
469	                        </div>
470	                      </details>
471	                    )}
472	                  </div>
473	                ) : <p className="small muted">No feature was evaluated, so there is no BMW price-list position for it.</p>}
474	                  <CompetitorPanel compare={comp} analysis={compAnalysis} state={compState} error={compError} onShowNode={showNode}
475	                    onRetry={() => (comp?.competition_id ? analyseCompetitors(comp.competition_id) : evaluation && loadCompetitors(evaluation.spec))} />
476	                </>)}
477	                {tab === "graph" && (
478	                  <Suspense fallback={<div className="skeleton" style={{ height: 320 }} />}>
479	                    <EvidenceGraph evaluation={evaluation} focus={focus} onFocus={setFocus} onOpenFull={openGraph} />
480	                  </Suspense>
481	                )}
482	                {tab === "verification" && <VerificationReport explained={explained} facts={evaluation.facts} />}
483	              </div>
484	            </>
485	          )}
486	        </section>
487	        )}
488	        </div>
489	      </div>
490	
