496	
497	      <aside className="ws__side side" aria-label="Side panel">
498	        <div className="side__head">
499	          <ol className="side__steps" aria-label="Steps">
500	            {STEPS.map((id, i) => (
501	              <li key={id}>
502	                <button type="button" className={`side__step ${id === panel ? "side__step--on" : ""} ${id === current ? "side__step--now" : ""}`}
503	                  aria-current={id === panel ? "step" : undefined} aria-label={`Step ${i + 1}: ${STEP_TITLE[id]}`} onClick={() => selectStep(id)}>
504	                  <ActorIcon actor={id} size={14} />
505	                </button>
506	              </li>
507	            ))}
508	          </ol>
509	          <p className="side__eyebrow">Step {STEPS.indexOf(panel) + 1} of 6, {ACTOR_LABEL[panel]}</p>
510	          <h2 className="side__title">{STEP_TITLE[panel]}</h2>
511	          {panel !== current && (
