524	            ) : interpretError ? (
525	              <div className="stack">
526	                <p className="note note--error">The idea could not be matched: {interpretError}</p>
527	                <button className="btn btn--small" onClick={() => interpret(submitted)}>Try again</button>
528	              </div>
