530	              <div className="stack">
531	                <p>{interp.spec.summary}</p>
532	                <p className="small muted">
533	                  {interp.spec.features.length ? `Suggested: ${interp.spec.features.map((f) => f.feature).join(", ")}.` : "No exact match."}{" "}
534	                  {interp.candidates.length} related topics were found in the customer feedback for you to choose from.
535	                </p>
536	                {phase === "review" && <button className="btn btn--small" onClick={() => setPanel("you")}>Next: choose what to check</button>}
537	              </div>
538	            ) : null
539	          )}
540	
541	          {panel === "you" && (
542	            interp && draft ? (
543	              <SpecReview compact interp={interp} draft={draft} setDraft={setDraft} busy={phase === "evaluating"}
544	                onEvaluate={() => evaluate(draft, policy, true)} confirmed={phase === "evaluating" || phase === "done"} />
545	            ) : <Waiting>This step opens once your idea has been broken down into topics.</Waiting>
546	          )}
547	
548	          {panel === "engine" && (
549	            evaluation ? (
550	              <div className="stack">
551	                {fr ? <EngineSummary feature={fr} final={final} /> : <p className="small">No topic matched directly, so there is nothing to score. See the report for the nearest topics.</p>}
552	                {policy && policyData && (
553	                  <div className="stack">
554	                    <button className="btn btn--outline btn--small" onClick={() => setShowPolicy((s) => !s)} aria-expanded={showPolicy}>
555	                      {showPolicy ? "Hide the decision policy" : "Adjust the decision policy"}
556	                    </button>
557	                    <p className="caption">Changing the policy recomputes the numbers instantly. The written brief is then marked out of date.</p>
558	                    {showPolicy && (
559	                      <PolicyPanel policy={policy} defaults={policyData.default} hash={evaluation.result.policy_hash} onChange={editPolicy}
