566	              <Working title="Scoring against the data">Every series and market is scored from customer feedback, studies and sales. No AI is used.</Working>
567	            ) : <Waiting>This step starts when you have chosen what to check.</Waiting>
568	          )}
569	
570	          {(panel === "explainer" || panel === "verifier") && (
571	            explainState === "running" ? (
572	              <Working title={panel === "explainer" ? "Writing the brief" : "Checking every sentence"}>
573	                The explainer writes the brief from the facts only, citing a fact for every sentence. The verifier then checks numbers, labels,
574	                quotes and scope by rule and asks a second model whether the facts support each sentence. A failing sentence is rewritten once,
575	                then removed. Both run in one request of about 20 to 50 seconds.
576	              </Working>
577	            ) : explained ? (
578	              <div className="stack">
579	                <p>
580	                  <strong>{explained.verification.n_verified} sentences</strong> passed every check
581	                  {explained.verification.n_removed ? `, ${explained.verification.n_removed} were removed` : ", none were removed"}
582	                  {explained.verification.rewritten.length ? `. ${explained.verification.rewritten.length} were sent back once and fixed.` : "."}
583	                </p>
584	                <p className="small muted">Click the nodes under steps 4 and 5 to see each section and each check.</p>
585	                <button className="btn btn--outline btn--small" onClick={() => setTab("verification")}>Open the verification report</button>
586	              </div>
587	            ) : explainState === "stale" || explainState === "error" ? (
588	              <div className="stack">
589	                <p className="note note--warn">{explainState === "stale" ? "The policy changed, so the brief is out of date." : `The brief failed: ${explainError}`}</p>
590	                {evaluation && <button className="btn btn--small" onClick={() => explain(evaluation.evaluation_id)}>Write the brief again</button>}
591	              </div>
592	            ) : explainState === "unavailable" ? (
593	              <p className="note note--warn">The writing agents are not available. {explainError}</p>
594	            ) : <Waiting>This step starts after the evidence is computed.</Waiting>
595	          )}
596	
597	          {panel === "brief" && (
598	            evaluation ? (
599	              <div className="stack-lg">
600	                {features.map((f) => (
601	                  <div key={f.feature} className="stack">
602	                    {final && <p className="side__answer">{bottomLine(f).text}</p>}
603	                    <DecisionForm result={evaluation.result} feature={f} />
604	                  </div>
605	                ))}
606	                {features.length === 0 && <p className="small muted">Pick a related topic in step 2 to record a decision against its evidence.</p>}
607	                {!final && <p className="caption">The summary appears once the brief is written and fact-checked.</p>}
608	              </div>
609	            ) : <Waiting>Your decision comes last, after the report is ready.</Waiting>
610	          )}
611	        </div>
612	      </aside>
613	    </div>
614	  );
615	}
616	
